function App() {
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');

    if (saved === null) {
      return false;
    }

    try {
      return JSON.parse(saved);
    } catch {
      return false;
    }
  });

  useEffect(() => {
    localStorage.setItem(
      'darkMode',
      JSON.stringify(darkMode)
    );

    document.documentElement.setAttribute(
      'data-theme',
      darkMode ? 'dark' : 'light'
    );
  }, [darkMode]);

  return (
    <div className="App">
      <Header
        darkMode={darkMode}
        setDarkMode={setDarkMode}
      />

      <Hero />

      <QuranSection />

      <Mission />

      <Projects />

      <Stats />

      <DonateSection />

      <GetInvolved />

      <Contact />

      <Footer />
    </div>
  );
}
